import { test, expect } from '@playwright/test';
import { prepareReadOnly, openCalculator, fillInputs, expectResult, SET1, DEVICES } from './calculator.helpers';

test.use({ serviceWorkers: 'block' });

test.describe('Калькулятор — результаты, пояснения, дисклеймер', () => {
  for (const tag of DEVICES) {
    test(`«מונחים שכדאי להכיר» — 5 терминов, дисклеймер, нет рекомендаций купить/не купить #22ce3e ${tag} @prod-safe`, async ({ page, context }) => {
      await prepareReadOnly(context);
      await openCalculator(page);
      await fillInputs(page, SET1);
      await expectResult(page, 'תזרים חודשי משוער', '14,250 ₪');

      const glossary = page.getByRole('heading', { level: 2, name: 'מונחים שכדאי להכיר', exact: true });
      await expect(glossary).toBeVisible();
      const terms = page.locator('section[aria-labelledby="glossary-heading"] dt');
      for (const term of ['מחזור מכירות', 'רווח תפעולי', 'רווח לפני מס', 'תזרים', 'שכר בעלים']) {
        await expect(terms.filter({ hasText: new RegExp(`^${term}$`) }), `термин «${term}»`).toHaveCount(1);
      }

      await expect(page.getByText(/אינו ייעוץ פיננסי/).first()).toBeVisible();

      const body = await page.locator('body').innerText();
      for (const phrase of ['כדאי לקנות', 'לא כדאי', 'מומלץ לרכוש']) {
        expect(body, `нет «${phrase}»`).not.toContain(phrase);
      }
    });
  }
});
